int main() {
    int x = 42;
    int *ptr = &x;      // ptr holds the address of x

    printf("%d\n", *ptr);  // 42  (dereference)
    *ptr = 7;                // write through the pointer
    printf("%d\n", x);      // 7

    int *null_ptr = NULL;    // points nowhere — check before deref
    return 0;
}

