// Common segfault causes
int *p = nullptr;
*p = 5;            // dereferencing null → segfault

int arr[3];
arr[100] = 1;      // out-of-bounds write → may segfault

int *q = new int(5);
delete q;
*q = 7;            // use-after-free → segfault

// Fix: check pointers and stay in bounds
if (p) *p = 5;

